import { HttpResponsePointer, ResolverResult, HttpResponse } from '../config';

export async function resolveHttpResponse(pointer: HttpResponsePointer): Promise<ResolverResult> {
  if (pointer.type !== 'httpResponse') {
    return { shape: 'error', body: 'Invalid pointer type' };
  }

  try {
    const response = await fetch(pointer.url);
    const body = await response.text();
    return { shape: 'httpResponse', body: { status: response.status, body: body } };
  } catch (error: any) {
    return { shape: 'error', body: `Failed to fetch URL: ${error.message}` };
  }
}
